begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id) values('f1000000-0000-4000-8000-000000000001'),('f1000000-0000-4000-8000-000000000002'),('f1000000-0000-4000-8000-000000000003');
insert into profiles(id,display_name,consented_at) select id,'Received fixture',now() from auth.users where id::text like 'f1000000-%';
insert into families(id,name) values('f2000000-0000-4000-8000-000000000001','Received family');
insert into family_members(family_id,user_id,role) values('f2000000-0000-4000-8000-000000000001','f1000000-0000-4000-8000-000000000001','owner'),('f2000000-0000-4000-8000-000000000001','f1000000-0000-4000-8000-000000000002','viewer');
insert into children(id,family_id,name,sex,birth_date) values('f3000000-0000-4000-8000-000000000001','f2000000-0000-4000-8000-000000000001','Received baby','female',current_date);
insert into children(id,family_id,name,sex,birth_date) values('f3000000-0000-4000-8000-000000000002','f2000000-0000-4000-8000-000000000001','Second baby','female',current_date);
insert into child_access(child_id,family_id,user_id,role) values('f3000000-0000-4000-8000-000000000001','f2000000-0000-4000-8000-000000000001','f1000000-0000-4000-8000-000000000002','viewer');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f1000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select save_received_record('f4000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001','{"kind":"gift","sender_name":"할머니","title":"그림책","occurred_at":"2026-10-29T00:00:00Z","timezone":"Asia/Seoul"}')$$,'owner saves a gift');
select is((select sender_name from child_records where id='f4000000-0000-4000-8000-000000000001'),'할머니','giver persists');
select is((select title from child_records where id='f4000000-0000-4000-8000-000000000001'),'그림책','gift title persists');
select save_received_record('f4000000-0000-4000-8000-000000000002','f3000000-0000-4000-8000-000000000001','{"kind":"allowance","sender_name":"아빠","received_amount":10000,"received_currency":"KRW","occurred_at":"2026-10-29T01:00:00Z","timezone":"Asia/Seoul"}');
select save_received_record('f4000000-0000-4000-8000-000000000003','f3000000-0000-4000-8000-000000000001','{"kind":"allowance","sender_name":"이모","received_amount":12.50,"received_currency":"USD","occurred_at":"2026-10-29T02:00:00Z","timezone":"Asia/Seoul"}');
select is((select received_amount from child_records where id='f4000000-0000-4000-8000-000000000003'),12.50::numeric,'decimal amount is exact');
select is((select received_currency from child_records where id='f4000000-0000-4000-8000-000000000003'),'USD','currency remains per record');
select throws_ok($$select save_received_record(gen_random_uuid(),'f3000000-0000-4000-8000-000000000001','{"kind":"allowance","sender_name":"아빠","received_amount":0,"received_currency":"KRW","occurred_at":"2026-10-29T00:00:00Z","timezone":"UTC"}')$$,'23514',null,'non-positive amount rejected');
select throws_ok($$select save_received_record(gen_random_uuid(),'f3000000-0000-4000-8000-000000000001','{"kind":"allowance","sender_name":"아빠","received_amount":1.001,"received_currency":"USD","occurred_at":"2026-10-29T00:00:00Z","timezone":"UTC"}')$$,'23514',null,'sub-cent amount rejected');
select throws_ok($$select save_received_record(gen_random_uuid(),'f3000000-0000-4000-8000-000000000001','{"kind":"gift","title":"책","occurred_at":"2026-10-29T00:00:00Z","timezone":"UTC"}')$$,'23514',null,'giver required');
select save_received_record('f4000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001','{"kind":"gift","sender_name":"할머니","title":"수정한 그림책","occurred_at":"2026-10-29T00:00:00Z","timezone":"Asia/Seoul"}',1);
select is((select version from child_records where id='f4000000-0000-4000-8000-000000000001'),2,'edit increments version');
select throws_ok($$select save_received_record('f4000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001','{"kind":"gift","sender_name":"아빠","title":"오래된 편집","occurred_at":"2026-10-29T00:00:00Z","timezone":"UTC"}',1)$$,'P0001','conflict','stale edit rejected');
select throws_ok($$select save_received_record('f4000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000002','{"kind":"gift","sender_name":"아빠","title":"다른 아이로 이동","occurred_at":"2026-10-29T00:00:00Z","timezone":"UTC"}',2)$$,'42501','forbidden','owner cannot move another child record by ID');
select set_config('request.jwt.claims','{"sub":"f1000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is((select count(*)::int from child_records where child_id='f3000000-0000-4000-8000-000000000001'),3,'invited viewer reads records');
select throws_ok($$select save_received_record(gen_random_uuid(),'f3000000-0000-4000-8000-000000000001','{"kind":"gift","sender_name":"아빠","title":"책","occurred_at":"2026-10-29T00:00:00Z","timezone":"UTC"}')$$,'42501','forbidden','viewer cannot write');
select throws_ok($$select delete_child_record('f4000000-0000-4000-8000-000000000001')$$,'42501','forbidden','viewer cannot delete');
select set_config('request.jwt.claims','{"sub":"f1000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select is((select count(*)::int from child_records where child_id='f3000000-0000-4000-8000-000000000001'),0,'another family cannot read');
reset role;
select ok(not has_function_privilege('anon','public.save_received_record(uuid,uuid,jsonb,integer)','execute'),'anonymous cannot execute saver');

set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f1000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is((select total_amount::numeric from received_allowance_totals('f3000000-0000-4000-8000-000000000001') where is_total and currency='KRW'),10000::numeric,'KRW grand total is separate');
select is((select total_amount::numeric from received_allowance_totals('f3000000-0000-4000-8000-000000000001') where is_total and currency='USD'),12.50::numeric,'USD grand total is separate');
select is((select total_amount::numeric from received_allowance_totals('f3000000-0000-4000-8000-000000000001') where not is_total and sender_name='아빠' and currency='KRW'),10000::numeric,'giver subtotal persists');
select is((select total_count from received_gift_senders('f3000000-0000-4000-8000-000000000001') where sender_name='할머니'),1::bigint,'gift sender group counts all gifts');
reset role;
insert into child_records(id,child_id,service,kind,occurred_at,record_timezone,sender_name,received_amount,received_currency) select gen_random_uuid(),'f3000000-0000-4000-8000-000000000001','activity','allowance',now(),'UTC','아빠',100,'KRW' from generate_series(1,25);
set local role authenticated;
select is((select total_amount::numeric from received_allowance_totals('f3000000-0000-4000-8000-000000000001') where is_total and currency='KRW'),12500::numeric,'summary includes records outside first page');
select is((select count(*)::int from received_allowance_totals('f3000000-0000-4000-8000-000000000002')),0,'sibling totals stay separate');
reset role;
insert into storage.objects(bucket_id,name,metadata) select 'child-care-photos','f1000000-0000-4000-8000-000000000001/f3000000-0000-4000-8000-000000000001/f4000000-0000-4000-8000-000000000001/f5000000-0000-4000-8000-000000000001.webp'||suffix,'{"mimetype":"image/webp","size":100}'::jsonb from unnest(array['','.display-v1-480.webp','.display-v1-1600.webp']) suffix;
set local role authenticated;
select lives_ok($$select save_received_record('f4000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001','{"kind":"gift","sender_name":"할머니","title":"사진 선물","occurred_at":"2026-10-29T00:00:00Z","timezone":"UTC","gift_photo":{"id":"f5000000-0000-4000-8000-000000000001","path":"f1000000-0000-4000-8000-000000000001/f3000000-0000-4000-8000-000000000001/f4000000-0000-4000-8000-000000000001/f5000000-0000-4000-8000-000000000001.webp","size":100}}',2)$$,'gift attaches one fully uploaded private photo');
select is((select count(*)::int from child_record_photos where record_id='f4000000-0000-4000-8000-000000000001'),1,'gift has exactly one photo');
select ok((select variants_ready from child_record_photos where id='f5000000-0000-4000-8000-000000000001'),'display variants are ready at commit');
select is((select count(*)::int from growth_diary_photo('f5000000-0000-4000-8000-000000000001')),0,'gift photo never enters public diary photo endpoint');
select throws_ok($$select add_child_record_photo(gen_random_uuid(),'f4000000-0000-4000-8000-000000000001','image/webp',100)$$,'42501','forbidden','diary attachment API cannot add a second gift photo');
select throws_ok($$select save_received_record('f4000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001','{"kind":"gift","sender_name":"할머니","title":"오래된 삭제","occurred_at":"2026-10-29T00:00:00Z","timezone":"UTC","remove_photo_id":"f5000000-0000-4000-8000-000000000001"}',2)$$,'P0001','conflict','stale edit cannot remove the photo');
select is((select count(*)::int from child_record_photos where record_id='f4000000-0000-4000-8000-000000000001'),1,'stale failure preserves old photo');
select throws_ok($$select save_received_record('f4000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001','{"kind":"gift","sender_name":"할머니","title":"잘못된 삭제","occurred_at":"2026-10-29T00:00:00Z","timezone":"UTC","remove_photo_id":"f5000000-0000-4000-8000-000000000099"}',3)$$,'22023','invalid photo removal','foreign photo ID rejected');
select set_config('request.jwt.claims','{"sub":"f1000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is((select count(*)::int from child_record_photos where record_id='f4000000-0000-4000-8000-000000000001'),1,'family viewer reads gift photo');
select is((select total_amount::numeric from received_allowance_totals('f3000000-0000-4000-8000-000000000001') where is_total and currency='KRW'),12500::numeric,'viewer reads allowance summary');
select set_config('request.jwt.claims','{"sub":"f1000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select throws_ok($$select received_allowance_totals('f3000000-0000-4000-8000-000000000001')$$,'42501','forbidden','other family cannot obtain totals');
select throws_ok($$select received_gift_senders('f3000000-0000-4000-8000-000000000001')$$,'42501','forbidden','other family cannot enumerate gift senders');
select is((select count(*)::int from child_record_photos where record_id='f4000000-0000-4000-8000-000000000001'),0,'other family cannot read gift photo');
select set_config('request.jwt.claims','{"sub":"f1000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select save_received_record('f4000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001','{"kind":"gift","sender_name":"할머니","title":"사진 제거","occurred_at":"2026-10-29T00:00:00Z","timezone":"UTC","remove_photo_id":"f5000000-0000-4000-8000-000000000001"}',3);
select is((select count(*)::int from child_record_photos where record_id='f4000000-0000-4000-8000-000000000001'),0,'photo removal persists');
reset role;
select is((select count(*)::int from child_photo_cleanup where path like '%f5000000-0000-4000-8000-000000000001.webp%'),3,'photo removal queues original and both variants');
select ok(not has_function_privilege('anon','public.received_allowance_totals(uuid)','execute'),'anonymous cannot execute summary');

select * from finish();
rollback;
